import xarray as xr
import fsspec
import numpy as np
from datetime import datetime

fs = fsspec.filesystem('onedata')

# Check what's actually in the directory
files = fs.ls('/icsa2027_data_20261101T090944Z/s1z')
print(f"Total files in directory: {len(files)}")

# Check if there are any files from 2004 or 1992-2002
matching_files = []
for f in files:
    if f.endswith('.nc'):
        date_str = f.split('_')[-1].replace('.nc', '')
        try:
            date_obj = datetime.strptime(date_str, '%Y%m%d')
            if 1980 <= date_obj.year <= 2020:
                matching_files.append((date_obj, f))
        except ValueError:
            continue

matching_files.sort()
print(f"Files with valid dates: {len(matching_files)}")

if matching_files:
    print("Date range:", matching_files[0][0], "to", matching_files[-1][0])

    # Check specific years
    years = {}
    for date_obj, fname in matching_files:
        year = date_obj.year
        if year not in years:
            years[year] = []
        years[year].append(fname)

    print("\nYears with data:")
    for year in sorted(years.keys()):
        print(f"  {year}: {len(years[year])} files")
else:
    print("No valid date files found")

